def apply_notification_menu_presentation(source):
    if 'internal fun HxChoiceSheet(' not in source:
        return source
    for transform in TRANSFORMS:
        assert source.count(transform['before']) == transform['count'], 'Notification transformation must match the exact old source'
        source = source.replace(transform['before'], transform['after'], transform['count'])
    return source
